// halcyon.score - the music behind the Halcyon demo.
//
// Ambient writing with a classical spine: a Lydian pedal that never resolves
// downward, an inner voice answering the bell in canon, and a bass that moves
// once a bar at most. The notes are here; the SOUND is built in
// demos/Halcyon.cpp - two wavetable pads, one morphing under its envelope and
// one under a free LFO, with a sine pair FM-ing each other for the bell.
//
// 6/8 rather than 4/4, and not for novelty: the whole piece is a slow three
// against a slower two, and the compound metre is what lets a part hold across
// the middle of a bar without a tie.
//
// The tempo counts BEATS, and in 6/8 a beat is an eighth - beatUnit is
// notational and never reaches the transport. So 208 here is a dotted quarter
// of about 69, which is the tempo this is actually written at. Reading it as
// 208 of anything you can tap is the mistake to avoid.

song {
  title "Halcyon"
  tempo 208 bpm
  meter 6/8
  grid  auto
  key   D lydian
  seed  0x4A1C0FDEED
}

channel pad {
  mixer    1
  range    D3..D5
  velocity 29 +- 5
}

channel veil {
  mixer    2
  range    A3..A5
  velocity 25 +- 6 per bar
}

channel sub {
  mixer    3
  range    D1..D3
  velocity 46 +- 3
}

channel bell {
  mixer    4
  range    D5..D6
  velocity 34 +- 9 per note
}

channel answer {
  mixer    5
  range    A4..A5
  velocity 26 +- 6 per bar
}

voicing wide {
  size     4 voices
  spread   open
  register D3..D5
  motion   smooth
  maxLeap  5
  bass     from-inversion
}

voicing airy {
  size     3 voices
  spread   shell
  register A3..A5
  motion   smooth
  maxLeap  4
}

// A bar of 6/8 is six eighths - three quarters - so a rhythm that fills one is
// written as a dotted half. A 1/1 here would run a third of the way into the
// next bar, which is the trap a compound metre sets for a rhythm copied out of
// a 4/4 score.
rhythm hold    { 1/2. }
rhythm breathe { 1/4 1/4 1/4 }
rhythm sway    { 1/4. 1/4. }
rhythm shimmer { 1/8 x5 - 1/8 }

harmony pedal {
  I 2 bars | II 2 bars | vi 2 bars | V 2 bars
}

harmony lift {
  II 2 bars | vi 2 bars | iii 2 bars | V 2 bars
}

section open {
  length 4 bars
  harmony {
    I 2 bars | II 2 bars
  }
  part pad {
    chords with wide
    rhythm hold
  }
}

section rise {
  length 8 bars
  harmony pedal
  part pad {
    chords with wide
    rhythm hold
  }
  part veil {
    chords with airy
    rhythm sway
  }
  part sub {
    line root
    rhythm hold
  }
}

section bloom {
  length 8 bars
  harmony lift
  part pad {
    chords with wide
    rhythm breathe
  }
  part veil {
    chords with airy
    rhythm sway
  }
  part sub {
    line root-fifth
    rhythm breathe
  }
  part bell {
    melody {
      rhythm       shimmer
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.3
      mute         1 of 4
      leap         max 7 resolve step
      align        bar
      cadence      choose [1 3 5] per instance
    }
  }
  part answer {
    imitate bell {
      delay     1 bar
      transpose -5
      mode      diatonic
    }
  }
}

section turn {
  length 8 bars
  harmony {
    vi 2 bars | iii 2 bars | II 2 bars | V 2 bars
  }
  part pad {
    chords with wide
    rhythm sway
  }
  part veil {
    chords with airy
    rhythm breathe
  }
  part sub {
    line root
    rhythm hold
  }
  part bell {
    melody {
      rhythm   sway
      contour  wave
      strong   chord-tones
      variance 0.25
      mute     1 of 3
      align    bar
    }
  }
  part answer {
    counterpoint against bell {
      rhythm               breathe
      articulation         legato
      parallel-fifths      forbid
      parallel-octaves     forbid
      voice-crossing       forbid
      dissonance-on-strong soft 3
      leaps                soft 1.5
      repeats              soft 1
    }
  }
}

section wane {
  length 8 bars
  harmony pedal
  part pad {
    chords with wide
    rhythm hold
  }
  part veil {
    chords with airy
    rhythm hold
  }
  part sub {
    line root
    rhythm hold
  }
  part bell {
    melody {
      rhythm   breathe
      contour  fall
      strong   chord-tones
      variance 0.2
      mute     1 of 3
    }
  }
}

section close {
  length 4 bars
  harmony {
    II 1 bar | vi 1 bar | I 2 bars
  }
  part pad {
    chords with wide
    rhythm hold
  }
  part sub {
    line root
    rhythm hold
  }
}

arrangement {
  open
  rise
  bloom
  turn
  bloom
  wane
  close
}

// rhodes.score - the music behind the Late Rhodes demo.
//
// A neo-soul ballad in Eb: rootless and drop-2 voicings over a walking-ish
// bass, secondary dominants, and a tritone substitution into the last cadence.
// The notes are here; the SOUND is built in demos/LateRhodes.cpp - and it is an
// FM electric piano, because that is what an electric piano IS: a sine carrier
// with a sine an octave above it folded into its phase, and a third slot for
// the tine.
//
// Swung, not straight. The rhythms below are written in triplet eighths, which
// is what puts the grid at twelve steps to a beat - the value the language
// derives rather than one anybody chose.

song {
  title "Late Rhodes"
  tempo 78 bpm
  meter 4/4
  grid  auto
  key   Eb major
  seed  0x5A17ED0C0A
}

channel rhodes {
  mixer    1
  range    Eb3..Eb5
  velocity 38 +- 11 per note
}

channel bass {
  mixer    2
  range    Eb1..Eb3
  velocity 47 +- 6 per bar
}

channel pad {
  mixer    3
  range    Bb3..Bb5
  velocity 22 +- 4
}

channel horn {
  mixer    4
  range    Eb4..Eb5
  velocity 39 +- 10 per note
}

voicing rootless {
  size     4 voices
  spread   rootless
  register Eb3..Eb5
  motion   smooth
  maxLeap  5
  bass     any
}

voicing spread {
  size     4 voices
  spread   drop2
  register Bb2..Bb4
  motion   smooth
  maxLeap  7
  bass     from-inversion
}

voicing upper {
  size     3 voices
  spread   shell
  register Bb3..Bb5
  motion   smooth
  maxLeap  4
}

// Long-short: a triplet quarter against a triplet eighth is the shuffle this is
// played with, and writing it out is the only way dew can hold it - a step grid
// has no swing knob, so the swing has to be in the grid itself.
rhythm swung   { 1/4t 1/8t 1/4t 1/8t 1/4t 1/8t 1/4t 1/8t }
rhythm comp    { 1/4 - 1/8 1/8 1/4 1/4 }
rhythm hold    { 1/1 }
rhythm walk    { 1/4 1/4 1/4 1/8 1/8 }
rhythm fill    { 1/8t x6 1/16 x4 1/4 }

harmony head {
  I 1 bar | vi 1 bar | ii 2 bars | V7 2 bars | I 2 bars
}

harmony turn {
  iii 1 bar | V7/ii 1 bar | ii 2 bars | bII7 1 bar | I 1 bar | IV 1 bar | V7 1 bar
}

section head {
  length 8 bars
  harmony head
  part rhodes {
    chords with rootless
    rhythm comp
  }
  part bass {
    line root-fifth
    rhythm walk
  }
}

section verse {
  length 8 bars
  harmony head
  part rhodes {
    chords with rootless
    rhythm comp
  }
  part bass {
    line root-third-fifth
    rhythm walk
  }
  part pad {
    chords with upper
    rhythm hold
  }
  part horn {
    melody {
      rhythm       swung
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.3
      mute         1 of 3
      leap         max 7 resolve step
      align        bar
      cadence      choose [1 3 5] per instance
    }
  }
}

section bridge {
  length 8 bars
  harmony turn
  part rhodes {
    chords with spread
    rhythm swung
  }
  part bass {
    line root-fifth
    rhythm walk
  }
  part pad {
    chords with upper
    rhythm hold
  }
  part horn {
    melody {
      rhythm   fill
      contour  rise
      strong   chord-tones
      variance 0.4
      mute     1 of 4
      align    bar
    }
  }
}

section reprise {
  length 8 bars
  harmony head
  part rhodes {
    chords with rootless
    rhythm swung
  }
  part bass {
    line root-third-fifth
    rhythm walk
  }
  part pad {
    chords with upper
    rhythm hold
  }
  part horn {
    melody {
      rhythm   swung
      contour  wave
      strong   chord-tones
      variance 0.25
      mute     1 of 3
      align    bar
      cadence  1
    }
  }
}

section tag {
  length 8 bars
  harmony {
    ii 2 bars | bII7 1 bar | I 1 bar | IV 2 bars | I 2 bars
  }
  part rhodes {
    chords with spread
    rhythm comp
  }
  part bass {
    line root
    rhythm hold
  }
  part pad {
    chords with upper
    rhythm hold
  }
}

arrangement {
  head
  verse
  bridge
  reprise
  tag
}

// ironmeter.score - the music behind the Iron Meter demo.
//
// Math rock in seven: a riff that regroups 2+2+3 against 3+2+2 over the same
// bar, a bridge that drops from Mixolydian into Phrygian without changing key
// centre, and a lead that has to fit its phrases into a bar that is one eighth
// short of the one it wants. The notes are here; the SOUND is built in
// demos/IronMeter.cpp, and so is the kit - a score writes pitched parts, and a
// drum part is placement rather than harmony.
//
// The tempo counts BEATS, and in 7/8 a beat is an eighth. 294 here is a quarter
// of about 147, which is the tempo this is played at.

song {
  title "Iron Meter"
  tempo 294 bpm
  meter 7/8
  grid  auto
  key   E mixolydian
  seed  0x17E80FEED5
}

channel guitar {
  mixer    1
  range    E2..E4
  velocity 51 +- 8 per note
}

channel bass {
  mixer    2
  range    E1..E3
  velocity 53 +- 5
}

channel keys {
  mixer    3
  range    B3..B5
  velocity 31 +- 7 per bar
}

channel lead {
  mixer    4
  range    E4..E6
  velocity 44 +- 10 per note
}

voicing stack {
  size     3 voices
  spread   open
  register E3..E5
  motion   parallel
  maxLeap  7
  bass     root
}

voicing tight {
  size     3 voices
  spread   close
  register B3..B5
  motion   smooth
  maxLeap  4
}

// A bar is seven eighths, and the two groupings the piece plays against each
// other are both written out. `drive` is 2+2+3; `push` is 3+2+2. Nothing in the
// language knows they are the same bar counted differently - that is the point
// of putting both in front of the reader.
rhythm drive { 1/4 1/4 1/4. }
rhythm push  { 1/4. 1/4 1/4 }
rhythm chug  { 1/8 x7 }
rhythm split { 1/8 1/8 1/4 1/8 1/8 1/8 }
rhythm lace  { 1/16 x6 1/8 1/8 1/4 }

harmony ground {
  I 2 bars | VII 2 bars | IV 2 bars | I 2 bars
}

harmony climb {
  IV 2 bars | v 2 bars | VII 2 bars | I 2 bars
}

// The bridge keeps E under it and changes what the scale does above it. A local
// key on a harmony block is how a piece modulates without the SONG's key - and
// therefore every other section's numerals - moving with it.
harmony dark {
  key E phrygian
  i 2 bars | bII 2 bars | i 2 bars | bVII 2 bars
}

section riff {
  length 8 bars
  harmony ground
  part guitar {
    chords with stack
    rhythm drive
  }
  part bass {
    line root
    rhythm push
  }
}

section verse {
  length 8 bars
  harmony ground
  part guitar {
    chords with stack
    rhythm drive
  }
  part bass {
    line root-fifth
    rhythm chug
  }
  part keys {
    chords with tight
    rhythm push
  }
  part lead {
    melody {
      rhythm       split
      articulation detached
      contour      wave
      strong       chord-tones
      variance     0.35
      mute         1 of 4
      leap         max 9 resolve step
      align        bar
    }
  }
}

section bridge {
  length 8 bars
  harmony dark
  part guitar {
    chords with stack
    rhythm chug
  }
  part bass {
    line root
    rhythm chug
  }
  part keys {
    chords with tight
    rhythm drive
  }
  part lead {
    melody {
      rhythm   lace
      contour  fall
      strong   scale-tones
      variance 0.45
      align    bar
    }
  }
}

section climb {
  length 8 bars
  harmony climb
  part guitar {
    chords with stack
    rhythm push
  }
  part bass {
    line root-fifth
    rhythm split
  }
  part keys {
    chords with tight
    rhythm chug
  }
  part lead {
    melody {
      rhythm   lace
      contour  rise
      strong   chord-tones
      variance 0.3
      align    bar
      cadence  choose [1 5] per instance
    }
  }
}

section coda {
  length 8 bars
  harmony {
    I 2 bars | IV 2 bars | VII 2 bars | I 2 bars
  }
  part guitar {
    chords with stack
    rhythm drive
  }
  part bass {
    line root
    rhythm drive
  }
  part keys {
    chords with tight
    rhythm drive
  }
}

arrangement {
  riff
  verse
  riff
  bridge
  climb
  riff
  coda
}

// nightfall.score - the music behind the Nightfall Waltz demo.
//
// A string quartet's worth of writing in D harmonic minor: a waltz theme, an
// answering voice under real counterpoint rules, and a canon at the fourth. The
// notes are here; the SOUND is built in demos/NightfallWaltz.cpp - detuned
// triangle stacks placed across the stereo field the way an ensemble sits, and
// nothing a dance mix would do to them.
//
// Every numeral below is BARE, and that is deliberate. An accidental reads
// against the major scale while a bare numeral reads against the mode, and
// harmonic minor already has a flat sixth - so `bVI` here would flatten it
// twice and land a semitone under the Bb this piece is about.

song {
  title "Nightfall Waltz"
  tempo 96 bpm
  meter 3/4
  grid  auto
  key   D harmonic-minor
  seed  0x0DE1AB0DE
}

channel violin {
  mixer    1
  range    D4..D6
  velocity 40 +- 9 per note
}

channel viola {
  mixer    2
  range    A3..A5
  velocity 35 +- 7 per bar
}

channel cello {
  mixer    3
  range    D2..D4
  velocity 43 +- 5
}

channel clarinet {
  mixer    4
  range    D4..A5
  velocity 32 +- 8 per bar
}

voicing chamber {
  size     3 voices
  spread   close
  register A3..A5
  motion   smooth
  maxLeap  4
  bass     root
}

voicing open {
  size     4 voices
  spread   drop2
  register D3..D5
  motion   smooth
  maxLeap  7
  bass     from-inversion
}

// A bar is three quarters. `turn` is the waltz figure the theme is built from;
// `flourish` is the only thing here that needs sixteenths, and it is what puts
// the grid at four steps to a beat rather than two.
rhythm waltz    { 1/4 1/4 1/4 }
rhythm hold     { 1/2. }
rhythm lilt     { 1/2 1/4 }
rhythm turn     { 1/4 1/8 1/8 1/4 }
rhythm flourish { 1/16 x4 1/8 1/8 1/4 }

harmony descent {
  i 2 bars | vii 1 bar | i 1 bar | iv 2 bars | V 2 bars
}

harmony answer {
  VI 2 bars | ii 2 bars | V 2 bars | i 2 bars
}

section theme {
  length 8 bars
  harmony descent
  part cello {
    line root
    rhythm waltz
  }
  part viola {
    chords with chamber
    rhythm waltz
  }
  part violin {
    melody {
      rhythm       turn
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.25
      leap         max 7 resolve step
      align        bar
      cadence      1
    }
  }
}

section reply {
  length 8 bars
  harmony answer
  part cello {
    line root-fifth
    rhythm lilt
  }
  part viola {
    chords with chamber
    rhythm waltz
  }
  part violin {
    melody {
      rhythm   flourish
      contour  wave
      strong   chord-tones
      variance 0.35
      align    bar
      cadence  choose [1 3] per instance
    }
  }
  part clarinet {
    counterpoint against violin {
      rhythm               turn
      articulation         detached
      parallel-fifths      forbid
      parallel-octaves     forbid
      direct-fifths        soft 2
      voice-crossing       forbid
      dissonance-on-strong soft 3
      leaps                soft 1.5
      repeats              soft 1
    }
  }
}

section develop {
  length 8 bars
  harmony {
    iv 2 bars | i 2 bars | VI 1 bar | ii 1 bar | V 2 bars
  }
  part cello {
    line root
    rhythm waltz
  }
  part viola {
    chords with open
    rhythm turn
  }
  part violin {
    melody {
      rhythm   flourish
      contour  rise
      strong   scale-tones
      variance 0.45
      leap     max 9 resolve step
      align    bar
    }
  }
  part clarinet {
    counterpoint against violin {
      rhythm               waltz
      parallel-fifths      forbid
      parallel-octaves     forbid
      voice-crossing       forbid
      dissonance-on-strong soft 2
      leaps                soft 2
      repeats              soft 1
    }
  }
}

section canon {
  length 8 bars
  harmony descent
  part cello {
    line root
    rhythm hold
  }
  part violin {
    melody {
      rhythm   turn
      contour  arch
      strong   chord-tones
      variance 0.2
      align    bar
    }
  }
  part clarinet {
    imitate violin {
      delay     1 bar
      transpose -3
      mode      diatonic
    }
  }
  part viola {
    chords with chamber
    rhythm waltz
  }
}

section recap {
  length 8 bars
  harmony descent
  part cello {
    line root-fifth
    rhythm waltz
  }
  part viola {
    chords with open
    rhythm waltz
  }
  part violin {
    melody {
      rhythm   turn
      contour  arch
      strong   chord-tones
      variance 0.15
      align    bar
      cadence  1
    }
  }
  part clarinet {
    counterpoint against violin {
      rhythm               lilt
      parallel-fifths      forbid
      parallel-octaves     forbid
      voice-crossing       forbid
      dissonance-on-strong soft 3
      leaps                soft 1.5
      repeats              soft 1
    }
  }
}

section coda {
  length 8 bars
  harmony {
    iv 2 bars | V 2 bars | i 4 bars
  }
  part cello {
    line root
    rhythm hold
  }
  part viola {
    chords with chamber
    rhythm hold
  }
  part violin {
    melody {
      rhythm   lilt
      contour  fall
      strong   chord-tones
      variance 0.15
      cadence  1
    }
  }
}

arrangement {
  theme
  reply
  develop
  canon
  recap
  coda
}
